begin;insert into public.security_permissions(codigo,modulo,nome,criticidade)values('official.export.read','integracoes','Consultar arquivos oficiais','sensivel'),('official.export.manage','integracoes','Gerar arquivos oficiais','critica')on conflict(codigo)do update set nome=excluded.nome;insert into public.security_role_permissions(role_id,permission_id)select r.id,p.id from public.security_roles r join public.security_permissions p on p.codigo in('official.export.read','official.export.manage')where r.codigo='tenant_admin'on conflict do nothing;create table public.official_export_layouts(id uuid primary key default gen_random_uuid(),code text not null,version text not null,effective_from date not null,effective_to date,schema_definition jsonb not null,unique(code,version));create table public.official_export_batches(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),layout_id uuid not null references public.official_export_layouts(id),reference_month date not null,status text not null,records_count int not null,file_content text not null,file_sha256 text not null,validation_errors jsonb not null default'[]',created_by uuid references public.profiles(id),created_at timestamptz default now(),check(status in('valido','invalido','enviado','aceito','rejeitado')),check(file_sha256~'^[0-9a-f]{64}$'));alter table public.official_export_batches enable row level security;do $$begin if to_regnamespace('auth')is not null then create policy official_exports on public.official_export_batches for all to authenticated using(private.has_tenant_permission(tenant_id,'official.export.read'))with check(private.has_tenant_permission(tenant_id,'official.export.manage'));end if;end$$;revoke all on public.official_export_batches from anon;do $$begin if exists(select 1 from pg_roles where rolname='authenticated')then grant select,insert,update on public.official_export_batches to authenticated;grant select on public.official_export_layouts to authenticated;end if;end$$;commit;
